CREATE OR REPLACE FUNCTION public.my_administrative_notices() RETURNS TABLE(id uuid,action text,reason text,created_at timestamptz,title text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.action,a.reason,a.created_at,CASE WHEN a.target_type='listing' THEN coalesce(l.data->>'title','Annonsen din') ELSE 'Profilen din' END FROM public.administrative_actions a LEFT JOIN public.listings l ON a.target_type='listing' AND l.id=a.target_id WHERE auth.uid() IS NOT NULL AND a.actor_id<>auth.uid() AND a.reason IS NOT NULL AND ((a.target_type='profile' AND a.target_id=auth.uid()::text) OR (a.target_type='listing' AND l.user_id=auth.uid())) ORDER BY a.created_at DESC LIMIT 100; $$;
REVOKE ALL ON FUNCTION public.my_administrative_notices() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_administrative_notices() TO authenticated;
CREATE POLICY "Restricted profiles cannot upload files" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(NOT public.profile_is_blocked(auth.uid()));
CREATE POLICY "Restricted profiles cannot replace files" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(NOT public.profile_is_blocked(auth.uid())) WITH CHECK(NOT public.profile_is_blocked(auth.uid()));
CREATE POLICY "Admins read private listing documentation" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='listing-documentation' AND public.has_role(auth.uid(),'admin'));